-- ترحيلُ تاريخ جمعية العدايل كاملًا — 2026-09-12
-- المصدر: EXCHANGESYS / ExAssociationAct / ExSyAccounts (أرشيف 2025)
--         + EXCHANGESYS2026 / ExSyAccounts2026
-- استحقاقات 59780.00 · مقبوضات 57880.00 · مصروفات 53650.00 · رصيد 4230.00

BEGIN;

-- ══ §0. الحارس ═══════════════════════════════════════════════════════
DO $guard$
DECLARE v_n int; v_bad text;
BEGIN
  SELECT count(*) INTO v_n FROM public.adeels;
  IF v_n <> 8 THEN RAISE EXCEPTION 'السجلّ يحمل % عديلاً لا ثمانية', v_n; END IF;
  SELECT string_agg(c, ', ' ORDER BY c) INTO v_bad
    FROM unnest(ARRAY['A-01','A-02','A-03','A-04','A-05','A-06','A-07','A-08']) c
   WHERE NOT EXISTS (SELECT 1 FROM public.adeels a WHERE a.adeel_code = c);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'أكوادٌ مفقودة: %', v_bad; END IF;
  SELECT string_agg(adeel_code, ', ') INTO v_bad FROM (
    SELECT adeel_code FROM public.adeels GROUP BY adeel_code HAVING count(*) > 1) d;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'كودٌ مكرّر: %', v_bad; END IF;
END $guard$;

-- ══ §1. مسحُ الماليّ وحدَه — السجلُّ والحساباتُ والرسائلُ تبقى ═════════
TRUNCATE TABLE public.payment_allocations, public.cash_movements, public.payments,
               public.receivables, public.disbursements, public.closed_periods
  RESTART IDENTITY;

-- ══ §2. الإعدادات ════════════════════════════════════════════════════
-- ⚠ fee_exceptions مفتاحُه شهرٌ تقويميّ لا فترة، فلا يسع سنتين مختلفتين:
--   2025 كانت 01 و02 و03 بـ200، و2026 هي 01 و06. المكتوبُ هنا قاعدةُ
--   المستقبل (2026)، أمّا شهورُ 2025 فمكتوبةٌ بقيمها صراحةً أدناه ومُقفلةٌ
--   كلُّها، فلا تمرّ على هذه القاعدة أبدًا.
UPDATE public.association_settings SET member_fee = 100.00,
       fee_exceptions = '{"01":"200.00","06":"200.00"}'::jsonb,
       system_start = DATE '2024-12-01' WHERE id = 1;

-- ══ §3. تعطيلُ محفّزَي التاريخ — يُعادان في §8 داخل المعاملة نفسِها ═══
ALTER TABLE public.payments      DISABLE TRIGGER trg_pay_stamp_time;
ALTER TABLE public.disbursements DISABLE TRIGGER trg_disb_stamp_time;

-- ══ §4. الأسماءُ والهواتف — من أرشيف 2025، وفيه لكلِّ رجلٍ رقمُه ═══════
UPDATE public.adeels a SET full_name = m.full_name,
       phone = nullif(m.phone,''), status = 'نشط'
  FROM (VALUES
    ('A-01', 'محمد حمد المانجا', '925339051'),
    ('A-02', 'المهدي عبدالله محمد بوفراج الشوبكي', '925093709'),
    ('A-03', 'هيثم مفتاح عبدالعظيم', '913799604'),
    ('A-04', 'ايمن صالح محمد صالح بلها', '923236289'),
    ('A-05', 'عبدالعزيز عطية حمد يونس الخشبي', '925890580'),
    ('A-06', 'سالم صالح الشيخي', '925820002'),
    ('A-07', 'عمران ونيس صالح ادم بوصخرة', '919778581'),
    ('A-08', 'رزق المبروك جلجال', '927624876')
  ) AS m(code, full_name, phone)
 WHERE a.adeel_code = m.code;

