-- ══ §8. الأشهرُ مُقفلةٌ كلُّها، ثمّ يُعاد الحارسان ══════════════════════
INSERT INTO public.closed_periods (period, closed_at, created)
SELECT period, min(created_at), count(*)::int FROM public.receivables GROUP BY period;
ALTER TABLE public.payments      ENABLE TRIGGER trg_pay_stamp_time;
ALTER TABLE public.disbursements ENABLE TRIGGER trg_disb_stamp_time;

-- ══ §9. لا نستقرّ على رقمٍ لم يُطابق المنظومة ═══════════════════════
DO $v$
DECLARE vr numeric; vp numeric; vd numeric; va numeric; n int; bad text;
BEGIN
  SELECT coalesce(sum(total),0) INTO vr FROM public.receivables WHERE status<>'ملغي';
  IF vr <> 59780.00 THEN RAISE EXCEPTION 'الاستحقاقات % لا 59780.00', vr; END IF;
  SELECT coalesce(sum(amount),0) INTO vp FROM public.payments WHERE status<>'ملغي';
  IF vp <> 57880.00 THEN RAISE EXCEPTION 'المقبوضات % لا 57880.00', vp; END IF;
  SELECT coalesce(sum(amount),0) INTO vd FROM public.disbursements WHERE status<>'ملغي';
  IF vd <> 53650.00 THEN RAISE EXCEPTION 'المصروفات % لا 53650.00', vd; END IF;
  SELECT coalesce(sum(amount),0) INTO va FROM public.payment_allocations;
  IF va <> vp THEN RAISE EXCEPTION 'خُصّص % من % — رصيدٌ مقدَّمٌ لم يكن في المصدر', va, vp; END IF;

  SELECT count(*) INTO n FROM public.receivables;
  IF n <> 176 THEN RAISE EXCEPTION 'عدد الاستحقاقات % لا 176', n; END IF;
  SELECT count(*) INTO n FROM public.payments;
  IF n <> 146 THEN RAISE EXCEPTION 'عدد الإيصالات % لا 146', n; END IF;
  SELECT count(*) INTO n FROM public.payment_allocations;
  IF n <> 177 THEN RAISE EXCEPTION 'عدد التخصيصات % لا 177', n; END IF;
  SELECT count(*) INTO n FROM public.disbursements;
  IF n <> 61 THEN RAISE EXCEPTION 'عدد السندات % لا 61', n; END IF;
  SELECT count(*) INTO n FROM public.cash_movements;
  IF n <> 146 THEN RAISE EXCEPTION 'عدد حركات الخزينة % لا 146', n; END IF;
  SELECT count(*) INTO n FROM public.closed_periods;
  IF n <> 22 THEN RAISE EXCEPTION 'عدد الأشهر المغلقة % لا 22', n; END IF;

  SELECT string_agg(t.x, E'\n  ') INTO bad FROM (
    SELECT r.id::text||': paid='||r.paid::text||' alloc='||coalesce(sum(a.amount),0)::text AS x
      FROM public.receivables r
      LEFT JOIN public.payment_allocations a ON a.receivable_id=r.id
     GROUP BY r.id, r.paid HAVING r.paid <> coalesce(sum(a.amount),0)) t;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'استحقاقٌ لا يطابق تخصيصاته:%', E'\n  '||bad; END IF;

  -- كلُّ رجلٍ على حدة — وهذا ما يمنع وقوعَ مالِ رجلٍ على آخر
  SELECT string_agg(t.x, E'\n  ') INTO bad FROM (
    SELECT a.adeel_code||': مستحق='||sum(r.total)::text||' مدفوع='||sum(r.paid)::text AS x
      FROM public.adeels a JOIN public.receivables r ON r.adeel_id=a.id
     GROUP BY a.adeel_code
    HAVING (a.adeel_code, sum(r.total), sum(r.paid)) NOT IN (
      ('A-01', 8315.00::numeric, 8315.00::numeric),
      ('A-02', 8315.00::numeric, 8315.00::numeric),
      ('A-03', 8315.00::numeric, 8015.00::numeric),
      ('A-04', 8315.00::numeric, 8015.00::numeric),
      ('A-05', 8315.00::numeric, 8015.00::numeric),
      ('A-06', 6885.00::numeric, 6585.00::numeric),
      ('A-07', 7555.00::numeric, 7155.00::numeric),
      ('A-08', 3765.00::numeric, 3465.00::numeric)
    )) t;
  IF bad IS NOT NULL THEN RAISE EXCEPTION 'أرقامُ عديلٍ لا تطابق المنظومة:%', E'\n  '||bad; END IF;

  IF (vp - vd) <> 4230.00 THEN RAISE EXCEPTION 'رصيد الخزينة % لا 4230.00', (vp-vd); END IF;
  RAISE NOTICE 'طابقت المنظومة: استحقاقات % · مقبوضات % · مصروفات % · رصيد %', vr, vp, vd, (vp-vd);
END $v$;

SELECT public.assert_two_doors_only();
SELECT public.assert_signin_intact();

COMMIT;

SELECT a.adeel_code AS "الكود", a.full_name AS "الاسم",
       to_char(sum(r.total),'FM99999990.00') AS "مستحق",
       to_char(sum(r.paid),'FM99999990.00')  AS "مدفوع",
       to_char(sum(r.total-r.paid),'FM99999990.00') AS "متبقٍ"
  FROM public.adeels a JOIN public.receivables r ON r.adeel_id=a.id
 GROUP BY a.adeel_code, a.full_name ORDER BY a.adeel_code;
